            if (regAddr == 0x8004u)
            {
                ++reads;
                return false;
            }
            if (regAddr == 0x2000u)
                regValue = (2u << 20) | (0u << 10) | 1u;
            else if (regAddr == 0x2004u)
                regValue = (2u << 20) | (1u << 10) | 1u;
            else if (regAddr == 0x8000u)
                regValue = 1000u;
            else
                regValue = 0;
            if (++reads >= 4)
                ctx.request_stop();
            return true;
        });

    auto poller = std::make_shared<BootProgressPoller>(
        ctx, mockDevice, std::chrono::milliseconds(0), 0, cb);
    ctx.run();
}

